$_SERVER['REMOTE_ADDR']='192.0.2.30';for($i=0;$i<180;$i++)$guard->postcode();guardNo(fn()=>$guard->postcode(),'consultas públicas de CEP possuem limite por endereço sem afetar limite de envios');
